package vn.edu.eaut.lab7.controller; import jakarta.servlet.*; import jakarta.servlet.http.*; import jakarta.servlet.annotation.*; import java.io.*; import java.util.*; import vn.edu.eaut.lab7.model.*; import vn.edu.eaut.lab7.repository.SanPhamRepository; @WebServlet("/cart") public class CartController extends HttpServlet {private final SanPhamRepository repo=new SanPhamRepository(); protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{HttpSession se=r.getSession();List<CartItem> c=get(se);String a=r.getParameter("action");int id=r.getParameter("id")==null?0:Integer.parseInt(r.getParameter("id"));if("add".equals(a)){SanPham p=repo.findById(id);if(p!=null){CartItem x=find(c,id);if(x==null)c.add(new CartItem(p,1));else x.setSoLuong(x.getSoLuong()+1);}se.setAttribute("cart",c);s.sendRedirect(r.getContextPath()+"/cart");return;}if("remove".equals(a)){c.removeIf(x->x.getSanPham().getId()==id);se.setAttribute("cart",c);s.sendRedirect(r.getContextPath()+"/cart");return;}if("update".equals(a)){int q=Integer.parseInt(r.getParameter("soLuong"));CartItem x=find(c,id);if(q<=0)c.removeIf(i->i.getSanPham().getId()==id);else if(x!=null)x.setSoLuong(q);se.setAttribute("cart",c);s.sendRedirect(r.getContextPath()+"/cart");return;}r.setAttribute("cart",c);r.getRequestDispatcher("/views/cart/list.jsp").forward(r,s);} @SuppressWarnings("unchecked") private List<CartItem> get(HttpSession s){Object o=s.getAttribute("cart");if(o==null){List<CartItem> c=new ArrayList<>();s.setAttribute("cart",c);return c;}return (List<CartItem>)o;} private CartItem find(List<CartItem> c,int id){return c.stream().filter(x->x.getSanPham().getId()==id).findFirst().orElse(null);}}